 const [state,setState]=(0,F.useState)({ready:enabled,calibrated:true,status:enabled?'ready':'off',message:enabled?'Simulated camera ready.':'Simulated camera is off.',hold:0,gesture:null});
 const sim=(0,F.useRef)({key:null,elapsed:0,wrongSent:false,sent:false,last:0,signature:''});
